struct Monitor {
    int shared_variable;
    int waiting_processes[2];
    int count;
};

struct Monitor* create_monitor() {
    struct Monitor* m = (struct Monitor*)malloc(sizeof(struct Monitor));
    m->shared_variable = 0;
    m->count = 0;
    m->waiting_processes[0] = -1;
    m->waiting_processes[1] = -1;
    return m;
}

void set(struct Monitor* m, int process_id) {
    // Simulacija blokiranja i čekanja
    if (m->shared_variable == 1) {
        // Proces je blokiran, dodajemo ga u listu čekanja
        m->waiting_processes[m->count] = process_id;
        m->count++;
        // U stvarnom sistemu bi ovde čekao na semafor
        printf("Proces %d je blokiran i čeka da se promeni promenljiva.\n", process_id);
        return;
    }

    // Pristup je dozvoljen
    m->shared_variable = 1;
    printf("Proces %d je uspešno setovao promenljivu na 1.\n", process_id);

    // Ako postoje čekajući procesi, dozvolimo im pristup
    if (m->count > 0) {
        int next_process_id = m->waiting_processes[0];
        m->waiting_processes[0] = -1;
        m->count--;
        // U stvarnom sistemu bi ovde signalizovali čekajući proces
        printf("Dozvoljavamo procesu %d da nastavi.\n", next_process_id);
    }
}

void reset(struct Monitor* m, int process_id) {
    // Simulacija blokiranja i čekanja
    if (m->shared_variable == 0) {
        // Proces je blokiran, dodajemo ga u listu čekanja
        m->waiting_processes[m->count] = process_id;
        m->count++;
        // U stvarnom sistemu bi ovde čekao na semafor
        printf("Proces %d je blokiran i čeka da se resetuje promenljiva.\n", process_id);
        return;
    }

    // Pristup je dozvoljen
    m->shared_variable = 0;
    printf("Proces %d je uspešno resetovao promenljivu na 0.\n", process_id);

    // Ako postoje čekajući procesi, dozvolimo im pristup
    if (m->count > 0) {
        int next_process_id = m->waiting_processes[0];
        m->waiting_processes[0] = -1;
        m->count--;
        // U stvarnom sistemu bi ovde signalizovali čekajući proces
        printf("Dozvoljavamo procesu %d da nastavi.\n", next_process_id);
    }
}

// Primer korišćenja (simulacija)
int main() {
    struct Monitor* monitor = create_monitor();
    int p1 = 1;
    int p2 = 2;

    printf("--- Pokus P1 da setuje (inicijalno 0) ---\n");
    set(monitor, p1); // P1 uspeva

    printf("\n--- Pokus P2 da resetuje (trenutno 1) ---\n");
    reset(monitor, p2); // P2 je blokiran

    printf("\n--- Pokus P1 da setuje (trenutno 1) ---\n");
    set(monitor, p1); // P1 je blokiran

    printf("\n--- P1 uspeva da resetuje (simulacija da je P2 dozvoljen) ---\n");
    // U stvarnom sistemu, kada bi P2 dobio dozvolu, on bi izvršio reset.
    // Ovde simuliramo da P2 dobije dozvolu i izvrši reset
    monitor->shared_variable = 0; // Ručno menjanje stanja za simulaciju
    printf("Simulacija: P2 je dobio dozvolu i resetovao promenljivu.\n");
    reset(monitor, p2); // P2 sada uspeva

    printf("\n--- Pokus P1 da setuje (trenutno 0) ---\n");
    set(monitor, p1); // P1 uspeva

    // Oslobadanje memorije
    free(monitor);
    return 0;
}

